look.customCSS:
/* ───── 青瓷×焦茶 · 第一批 ───── */
[data-wk="chat"]{background:url("data:image/svg+xml;base64,PHN2ZyB4bWxucz0naHR0cDovL3d3dy53My5vcmcvMjAwMC9zdmcnIHdpZHRoPScyMicgaGVpZ2h0PScyMicgdmlld0JveD0nMCAwIDIyIDIyJz48Y2lyY2xlIGN4PSczJyBjeT0nMycgcj0nMS4zJyBmaWxsPScjRDlDREI0Jy8+PGNpcmNsZSBjeD0nMTQnIGN5PScxNCcgcj0nMS4zJyBmaWxsPScjRDlDREI0Jy8+PC9zdmc+") 0 0/22px 22px,#F3EBDA !important}
[data-wk="body"]{background:transparent !important}

/* 顶栏：米白底，下面一道焦茶线 */
[data-wk="chathead"]{background:#FBF6EA !important;border-bottom:1.6px solid #4A3A30 !important;box-shadow:none !important}
[data-wk="headink"],[data-wk="headink"] *{color:#4A3A30 !important}
[data-wk="headdim"]{color:#A79E92 !important}
[data-wk="chatback"] svg{stroke:#4A3A30 !important}
[data-wk="chathead"] [data-wk="avatar"],[data-wk="chathead"] img{border-radius:10px !important;box-shadow:0 0 0 1.6px #4A3A30 !important}
[data-wk="sameroom"],[data-wk="chatmore"]{width:30px !important;min-width:30px !important;height:30px !important;font-size:0 !important;color:transparent !important;padding:0 !important;border:none !important;box-shadow:none !important;background-color:transparent !important}
[data-wk="sameroom"]{background:url("data:image/svg+xml;base64,PHN2ZyB4bWxucz0naHR0cDovL3d3dy53My5vcmcvMjAwMC9zdmcnIHZpZXdCb3g9JzAgMCAyNCAyNCc+PHBhdGggZD0nTTQgMTEgTDEyIDQgTDIwIDExIFYyMCBINFonIGZpbGw9J25vbmUnIHN0cm9rZT0nIzRBM0EzMCcgc3Ryb2tlLXdpZHRoPScxLjYnIHN0cm9rZS1saW5lam9pbj0ncm91bmQnLz48L3N2Zz4=") center/22px no-repeat !important;margin-left:auto !important}
[data-wk="chatmore"]{background:url("data:image/svg+xml;base64,PHN2ZyB4bWxucz0naHR0cDovL3d3dy53My5vcmcvMjAwMC9zdmcnIHZpZXdCb3g9JzAgMCAyNCAyNCc+PGNpcmNsZSBjeD0nNScgY3k9JzEyJyByPScxLjYnIGZpbGw9JyM0QTNBMzAnLz48Y2lyY2xlIGN4PScxMicgY3k9JzEyJyByPScxLjYnIGZpbGw9JyM0QTNBMzAnLz48Y2lyY2xlIGN4PScxOScgY3k9JzEyJyByPScxLjYnIGZpbGw9JyM0QTNBMzAnLz48L3N2Zz4=") center/22px no-repeat !important}
[data-wk="chatmore"] *,[data-wk="sameroom"] *{opacity:0 !important}

/* 头像：圆角方块，焦茶细边 */
button[data-wk="avatar"],span[data-wk="avatar"],button[data-wk="avatar"] *,span[data-wk="avatar"] *{border-radius:10px !important}
button[data-wk="avatar"],span[data-wk="avatar"]:not([data-halo]){box-shadow:0 0 0 1.6px #4A3A30 !important}

/* 名字：只给我那边一个「Me」 */
[data-wk="name"][data-me="0"]{display:none !important}
[data-wk="name"][data-me="1"]{font-size:0 !important;margin:0 4px 6px !important}
[data-wk="name"][data-me="1"]::after{content:"Me" !important;font-size:12px !important;color:#4A3A30 !important;letter-spacing:.06em !important}

/* 气泡：焦茶描边；我的青瓷、角上一颗星；他的米白、里面「」两个角标、顶上探出一只小猫 */
[data-wk="bubble"][data-kind="text"]{position:relative !important;overflow:visible !important;border:1.6px solid #4A3A30 !important;border-radius:12px !important;color:#4A3A30 !important;padding:11px 22px !important;box-shadow:none !important}
[data-wk="bubble"][data-kind="text"][data-me="1"]{background:#A9D3C3 !important}
[data-wk="bubble"][data-kind="text"][data-me="0"]{background:url("data:image/svg+xml;base64,PHN2ZyB4bWxucz0naHR0cDovL3d3dy53My5vcmcvMjAwMC9zdmcnIHZpZXdCb3g9JzAgMCAxMiAxMic+PHBhdGggZD0nTTEgMTEgVjEgSDExJyBmaWxsPSdub25lJyBzdHJva2U9JyM0QTNBMzAnIHN0cm9rZS13aWR0aD0nMS42Jy8+PC9zdmc+") 8px 7px/11px 11px no-repeat,url("data:image/svg+xml;base64,PHN2ZyB4bWxucz0naHR0cDovL3d3dy53My5vcmcvMjAwMC9zdmcnIHZpZXdCb3g9JzAgMCAxMiAxMic+PHBhdGggZD0nTTExIDEgVjExIEgxJyBmaWxsPSdub25lJyBzdHJva2U9JyM0QTNBMzAnIHN0cm9rZS13aWR0aD0nMS42Jy8+PC9zdmc+") right 8px bottom 7px/11px 11px no-repeat,#FBF6EA !important}
[data-wk="bubble"][data-kind="text"]::before,[data-wk="bubble"][data-kind="text"]::after{content:none !important}
[data-wk="bubble"][data-kind="text"][data-me="1"]::after{content:"" !important;position:absolute !important;right:-10px !important;bottom:-10px !important;left:auto !important;top:auto !important;width:22px !important;height:22px !important;background:url("data:image/svg+xml;base64,") center/contain no-repeat !important;border:none !important;transform:none !important}
[data-wk="msg"][data-first="1"] [data-wk="bubble"][data-kind="text"][data-me="0"]{margin-top:22px !important}
[data-wk="msg"][data-first="1"] [data-wk="bubble"][data-kind="text"][data-me="0"]::before{content:"" !important;position:absolute !important;right:6px !important;left:auto !important;top:-25px !important;width:52px !important;height:26px !important;background:url("data:image/svg+xml;base64,") center bottom/contain no-repeat !important;border:none !important;transform:none !important}

/* 时间、已读：浅灰小字 */
[data-wk="time"] > span{background:#FBF6EA !important;color:#4A3A30 !important;border:1.6px solid #4A3A30 !important;border-radius:999px !important;padding:2px 12px !important;font-size:11px !important}
[data-wk="meta"]{color:#A79E92 !important;font-size:10.5px !important}
[data-wk="bubble"][data-kind="typing"]{background:#FBF6EA !important;border:1.6px solid #4A3A30 !important;border-radius:12px !important}
[data-wk="bubble"][data-kind="typing"]::before,[data-wk="bubble"][data-kind="typing"]::after{content:none !important}
[data-wk="typingdot"]{background:#4A3A30 !important}
[data-wk="narrink"]{background:#FBF6EA !important;border:1.6px solid #4A3A30 !important;border-radius:10px !important;color:#4A3A30 !important;padding:3px 10px !important}
[data-wk="sysnotetext"]{color:#A79E92 !important}

/* 底栏：米白底一道焦茶线；输入框圆角描边；发送键是「发送」两个字的青瓷块，角上一颗星 */
[data-wk="composer"]{background:#FBF6EA !important;border-top:1.6px solid #4A3A30 !important;align-items:center !important;gap:8px !important}
[data-wk="chatinput"]{background:#fff !important;border:1.6px solid #4A3A30 !important;border-radius:12px !important;color:#4A3A30 !important}
[data-wk="chatinput"]::placeholder{color:#A79E92 !important}
[data-wk="chatplus"],[data-wk="chatreply"]{width:30px !important;min-width:30px !important;height:30px !important;border:none !important;box-shadow:none !important;border-radius:0 !important;background-color:transparent !important}
[data-wk="chatplus"]{background:url("data:image/svg+xml;base64,") center/26px no-repeat !important}
[data-wk="chatreply"]{background:url("data:image/svg+xml;base64,") center/26px no-repeat !important}
[data-wk="send"]{order:99 !important;position:relative !important;overflow:visible !important;width:64px !important;min-width:64px !important;height:36px !important;border:1.6px solid #4A3A30 !important;border-radius:10px !important;background:#A9D3C3 !important;box-shadow:none !important;opacity:1 !important;margin-right:6px !important}
[data-wk="send"]::before{content:"发送" !important;position:absolute !important;inset:0 !important;display:flex !important;align-items:center !important;justify-content:center !important;font-size:14px !important;letter-spacing:.2em !important;color:#4A3A30 !important}
[data-wk="send"]::after{content:"" !important;position:absolute !important;right:-9px !important;bottom:-9px !important;width:18px !important;height:18px !important;background:url("data:image/svg+xml;base64,") center/contain no-repeat !important}
[data-wk="chatplus"] *,[data-wk="send"] *,[data-wk="chatreply"] *{opacity:0 !important}
[data-wk="chatplus"]:active,[data-wk="send"]:active,[data-wk="chatreply"]:active{transform:scale(.92) !important}
[data-wk="msg"][data-me="0"] [data-wk="name"]{display:none !important}
[data-wk="msg"][data-me="1"] [data-wk="meta"]{margin-right:14px !important}
